#!/usr/bin/env bash
# Question 1: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

(
case "${Q1_FAULT}" in
  containerd-stopped)
    systemctl disable --now containerd
    ;;
  ip-forward-and-containerd)
    sysctl -w net.ipv4.ip_forward=0 >/dev/null
    rm -f /etc/sysctl.d/k8s.conf
    systemctl disable --now containerd >/dev/null 2>&1 || true
    [[ "$(sysctl -n net.ipv4.ip_forward)" == "0" ]]
    [[ "$(systemctl is-enabled containerd 2>/dev/null || true)" != "enabled" ]]
    ;;
  cni-config-removed)
    mkdir -p "/var/tmp/cka-q1.cni"
    mv /etc/cni/net.d/*.conflist "/var/tmp/cka-q1.cni/"
    ! ls /etc/cni/net.d/*.conflist >/dev/null 2>&1 || { echo "could not move the CNI config" >&2; exit 1; }
    ;;
  containerd-config-invalid)
    cp -a /etc/containerd/config.toml "/var/tmp/cka-q1.containerd"
    printf '\n[plugins\n' >> /etc/containerd/config.toml
    systemctl restart containerd || true
    systemctl restart kubelet || true
    ;;
  cni-conflist-typo)
    f=$(ls /etc/cni/net.d/*.conflist 2>/dev/null | head -1)
    [[ -n "$f" ]] || { echo "no CNI conflist" >&2; exit 1; }
    cp -a "$f" "/var/tmp/cka-q1.cni-conflist"
    printf '{ "cniVersion": "0.3.1", "name": "broken", "plugins": [ { "type": "not-a-real-cni-plugin" } ]\n' > "$f"
    ! python3 -c "import json,sys; json.load(open(sys.argv[1]))" "$f" 2>/dev/null
    systemctl restart containerd || true
    systemctl restart kubelet || true
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  kubelet-stopped)
    systemctl disable --now kubelet
    ;;
  kubelet-binary-path)
    dropin=$(systemctl show kubelet -p DropInPaths --value | tr ' ' '\n' | grep 10-kubeadm.conf)
    sed -i 's#^ExecStart=/usr/bin/kubelet #ExecStart=/usr/local/bin/kubelet #' "$dropin"
    grep -q '^ExecStart=/usr/local/bin/kubelet ' "$dropin"
    systemctl daemon-reload
    systemctl restart kubelet || true
    ;;
  kubelet-config-invalid)
    sed -i -E 's/^kind: KubeletConfiguration$/kind: KubeletConfig/' /var/lib/kubelet/config.yaml
    grep -qE -- '^kind: KubeletConfig$' /var/lib/kubelet/config.yaml || { echo "could not edit /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-client-ca)
    sed -i -E 's#clientCAFile: /etc/kubernetes/pki/ca\.crt$#clientCAFile: /etc/kubernetes/pki/ca.pem#' /var/lib/kubelet/config.yaml
    grep -qE -- 'clientCAFile: /etc/kubernetes/pki/ca\.pem$' /var/lib/kubelet/config.yaml || { echo "could not edit /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-api-port)
    sed -i -E 's#^([[:space:]]*server: https://.*):6443$#\1:6444#' /etc/kubernetes/kubelet.conf
    grep -qE -- 'server: https://.*:6444$' /etc/kubernetes/kubelet.conf || { echo "could not edit /etc/kubernetes/kubelet.conf" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-extra-args)
    touch /etc/default/kubelet
    cp -a /etc/default/kubelet "/var/tmp/cka-q1.kubelet-default"
    grep -q '^KUBELET_EXTRA_ARGS=' /etc/default/kubelet || echo 'KUBELET_EXTRA_ARGS=' >> /etc/default/kubelet
    sed -i -E 's#^KUBELET_EXTRA_ARGS=(.*)$#KUBELET_EXTRA_ARGS=\1 --pod-max-pids-limit=100#' /etc/default/kubelet
    grep -qE -- '--pod-max-pids-limit=100' /etc/default/kubelet || { echo "could not edit /etc/default/kubelet" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  kubelet-conf-missing)
    mv /etc/kubernetes/kubelet.conf "/var/tmp/cka-q1.kubelet-conf"
    [[ ! -f /etc/kubernetes/kubelet.conf ]]
    systemctl restart kubelet || true
    ;;
  kubelet-swap-on)
    SWAP=/root/cka-swap
    dd if=/dev/zero of="$SWAP" bs=1M count=64 status=none
    chmod 600 "$SWAP"
    mkswap "$SWAP" >/dev/null
    swapon "$SWAP"
    swapon --show | grep -q cka-swap
    sed -i '/^failSwapOn:/d' /var/lib/kubelet/config.yaml
    echo 'failSwapOn: true' >> /var/lib/kubelet/config.yaml
    systemctl restart kubelet || true
    ;;
esac
)
